export const windowCalibration={version:1,reference:'nursery-cradle-v37.png fitted at 960×540, scale 1.05',horizontal:[-68,22,109,193,279],verticalTop:[303,363,443,522,600],verticalBottom:[301,360,440,519,580],topY:0,bottomY:279,horizontalBars:10,verticalBars:4};
export function panePolygons(input={}){const m=input.windowPaneCalibration||windowCalibration,dx=(input.precisionPaneX??305)-305,dy=(input.precisionPaneY??-20)+20,sx=(input.precisionPaneWidth??300)/300,sy=(input.precisionPaneHeight??320)/320,barScale=(input.precisionPaneBars??6)/6,polys=[];const edge=(col,y)=>m.verticalTop[col]+(m.verticalBottom[col]-m.verticalTop[col])*(y-m.topY)/(m.bottomY-m.topY),project=(x,y)=>{const imageScale=input._paneImageScale??1;return [480+(440+(x-440)*sx+dx-480)*imageScale+(input._paneImageX||0),270+(130+(y-130)*sy+dy-270)*imageScale+(input._paneImageY||0)]};for(let row=0;row<m.horizontal.length-1;row++)for(let col=0;col<m.verticalTop.length-1;col++){const top=m.horizontal[row]+m.horizontalBars*barScale/2,bottom=m.horizontal[row+1]-m.horizontalBars*barScale/2,left=m.verticalBars*barScale/2,right=left;polys.push([project(edge(col,top)+left,top),project(edge(col+1,top)-right,top),project(edge(col+1,bottom)-right,bottom),project(edge(col,bottom)+left,bottom)])}return polys}
